def _download_kml(url: str) -> bytes | None:
    """Fetch a single GTWO KMZ and return the extracted KML bytes; None on
    any network / HTTP failure."""
    import ipaddress, socket
    from urllib.parse import urlsplit
    _parts = urlsplit(str(url))
    if _parts.scheme.lower() == "file":
        raise ValueError("refusing file:// URL")
    try:
        _infos = socket.getaddrinfo(_parts.hostname, None) if _parts.hostname else []
    except OSError:
        _infos = []
    for _info in _infos:
        _addr = ipaddress.ip_address(_info[4][0])
        if (_addr.is_private or _addr.is_loopback or _addr.is_link_local
                or _addr.is_reserved or _addr.is_multicast or _addr.is_unspecified):
            raise ValueError("refusing non-public destination")
    req = urllib.request.Request(
        url, headers={"User-Agent": USER_AGENT},
    )
    try:
        with urllib.request.urlopen(req, timeout=FETCH_TIMEOUT_S) as resp:
            payload = resp.read()
    except Exception:  # noqa: BLE001 — network / 404 → degrade
        return None
    # NHC ships KMZ (zipped KML). If we somehow got a raw KML back
    # (test doubles, mirrored proxy), pass it through.
    if url.lower().endswith(".kmz"):
        try:
            return _kml_from_kmz(payload)
        except Exception:  # noqa: BLE001
            return None
    return payload
